import { ImageLoaderConfig } from '@angular/common';
import imageSizes from '../data/image-sizes.json';

// Intrinsic sizes and responsive variants are generated by scripts/generate-image-sizes.mjs
const sizes = imageSizes as Record<string, number[]>;
export const IMAGE_BREAKPOINTS = [480, 800, 1200, 1600];

/**
 * Intrinsic size of a bundled image, used for the width/height attributes that stop layout shift
 */
export function imageSize(src: string): { width: number; height: number } {
  const [width, height] = sizes[src] ?? [1200, 800];
  return { width, height };
}

/**
 * NgOptimizedImage loader: maps a requested width to the pre-generated `name-<width>.webp` file,
 * and falls back to the original when it is already narrower than the requested width
 */
export function responsiveImageLoader(config: ImageLoaderConfig): string {
  if (!config.width || !config.src.endsWith('.webp')) {
    return config.src;
  }
  const natural = sizes[config.src]?.[0] ?? Infinity;
  const width = IMAGE_BREAKPOINTS.find(w => w >= config.width! && w < natural);
  return width ? config.src.replace(/\.webp$/, `-${width}.webp`) : config.src;
}
